// DETAIL PANEL (bottom): clip editor on the left, device chain on the right
struct DetailPanel : Component, Timer
{
    DetailPanel (Session& s) : session (s), roll (s), audio (s), devices (s)
    {
        addAndMakeVisible (roll); addChildComponent (audio); addAndMakeVisible (devices);
        startTimerHz (15);
    }
    void refresh()
    {
        auto c = Session::alive (session.selClip.get()) ? session.selClip.get() : nullptr;
        auto mc = dynamic_cast<te::MidiClip*> (c);
        auto ac = dynamic_cast<te::AudioClipBase*> (c);
        roll.setVisible (ac == nullptr); audio.setVisible (ac != nullptr);
        if (mc != roll.clip.get()) roll.setClip (mc);
        if (ac != audio.clip.get()) audio.setClip (ac);
        devices.rebuild();
        repaint();
    }
    void timerCallback() override { if (roll.isVisible() && session.edit->getTransport().isPlaying()) roll.repaint(); }
    void paint (Graphics& g) override
    {
        g.setColour (sw::colour::line); g.drawHorizontalLine (0, 0, (float) getWidth());
        auto r = getLocalBounds().reduced (sw::space::m);
        sw::paintCard (g, editorArea (r).toFloat().expanded (6), 16.0f);
        g.setColour (sw::colour::text); g.setFont (sw::display (16.0f));
        auto c = Session::alive (session.selClip.get()) ? session.selClip.get() : nullptr;
        g.drawText (dynamic_cast<te::AudioClipBase*> (c) ? "AUDIO CLIP" : "MIDI", editorArea (r).removeFromTop (24).translated (0, -2), Justification::centredRight);
    }
    Rectangle<int> editorArea (Rectangle<int> r) const { return r.removeFromLeft (r.getWidth() * 3 / 5).reduced (6); }
    void resized() override
    {
        auto r = getLocalBounds().reduced (sw::space::m);
        auto ed = editorArea (r);
        roll.setBounds (ed); audio.setBounds (ed);
        r.removeFromLeft (r.getWidth() * 3 / 5);
        devices.setBounds (r.withTrimmedLeft (sw::space::l));
    }
    Session& session;
    PianoRoll roll; AudioClipEditor audio; DeviceChain devices;
};

//==============================================================================
// Rendering (used by the EXPORT dialog and by --selftest)
static te::LibLameEncoderAudioFormat& lame()
{
    // 1. a copy next to the exe (lets users swap in their own build, as the LGPL asks)
    // 2. the copy embedded in the exe, unpacked once into the app data folder
    // 3. the system library
    static te::LibLameEncoderAudioFormat f ([] {
        auto name = te::LibLameEncoderAudioFormat::getDefaultLibraryName();
        auto local = File::getSpecialLocation (File::currentExecutableFile).getSiblingFile (name);
        if (local.existsAsFile()) return local.getFullPathName();
       #if SW_EMBEDDED_LAME
        auto unpacked = settings().getFile().getSiblingFile (name);
        if (unpacked.getSize() != (int64) LameData::libmp3lame_dllSize)
            unpacked.replaceWithData (LameData::libmp3lame_dll, (size_t) LameData::libmp3lame_dllSize);
        if (unpacked.existsAsFile()) return unpacked.getFullPathName();
       #endif
        return name; }());
    return f;
}

struct ExportOptions
{
    bool wav = true;
    int bitDepth = 24;
    double sampleRate = 48000.0;
    int mp3Quality = 0;      // index into the EXPORT dialog's MP3 list
    bool loopOnly = false;
    int normalise = 0;       // 0 off, 1 peak 0 dB, 2 peak -1 dB, 3 -14 LUFS, 4 -9 LUFS
    bool dither = true, masterFx = true;
};

static bool renderEdit (te::Edit& edit, const File& dest, const ExportOptions& o)
{
    static WavAudioFormat wavFormat;
    if (! o.wav && ! lame().isLibraryLoaded()) return false;
    te::Renderer::Parameters p (edit);
    p.tracksToDo = te::toBitSet (te::getAllTracks (edit));   // empty set renders nothing
    p.destFile = dest;
    p.audioFormat = o.wav ? (AudioFormat*) &wavFormat : (AudioFormat*) &lame();
    p.bitDepth = o.wav ? o.bitDepth : 16;
    p.sampleRateForAudio = o.wav ? o.sampleRate : jmin (48000.0, o.sampleRate);
    if (! o.wav)   // map our short list onto LAME's option list
    {
        const char* names[] = { "320 Kb/s CBR", "256 Kb/s CBR", "192 Kb/s CBR", "128 Kb/s CBR",
                                "VBR quality 0 (best)", "VBR quality 2", "VBR quality 4 (normal)" };
        p.quality = jmax (0, lame().getQualityOptions().indexOf (names[jlimit (0, 6, o.mp3Quality)]));
    }
    auto& tc = edit.getTransport();
    p.time = o.loopOnly ? tc.getLoopRange() : te::TimeRange (te::TimePosition(), edit.getLength());
    p.ditheringEnabled = o.wav && o.dither && p.bitDepth < 32;
    p.useMasterPlugins = o.masterFx;
    p.canRenderInMono = false;
    switch (o.normalise)
    {
        case 1: p.shouldNormalise = true; p.normaliseToLevelDb = 0.0f; break;
        case 2: p.shouldNormalise = true; p.normaliseToLevelDb = -1.0f; break;
        case 3: p.shouldNormaliseByLUFS = true; p.normaliseToLevelDb = -14.0f; break;
        case 4: p.shouldNormaliseByLUFS = true; p.normaliseToLevelDb = -9.0f; break;
        default: break;
    }
    tc.stop (false, false);
    // ponytail: renders on the message thread (UI waits); move to a background job if songs get long
    return te::Renderer::renderToFile ("Export", p).existsAsFile();
}

